/*
 * DiagData: CAN ID 0x400 (standard), 8 bytes, sender Tester
 * Diagnostic data message.
 * Second line of this comment.
 *
 * C struct generated by CanViewer from demo.dbc.
 * Each member holds the raw value of a signal; physical value = raw * factor + offset.
 */
#include <stdint.h>

#define DIAGDATA_ID 0x400u
#define DIAGDATA_IS_EXTENDED 0
#define DIAGDATA_LENGTH 8u

typedef struct {
    /* start bit 0, 8 bits, Intel, unsigned, factor 1, offset 0, range 0 .. 255, multiplexor */
    uint8_t MuxSelector;
    /* start bit 8, 16 bits, Intel, unsigned, factor 0.001, offset 0, range 0 .. 65.535 V, when MuxSelector == 0 */
    uint16_t SensorVoltage;
    /* start bit 8, 16 bits, Intel, unsigned, factor 0.01, offset 0, range 0 .. 655.35 A, when MuxSelector == 1 */
    uint16_t SensorCurrent;
    /* start bit 8, 16 bits, Intel, unsigned, factor 1, offset 0, range 0 .. 65535, when MuxSelector == 2 */
    uint16_t ErrorCode;
} DiagData_t;
